mapper.select:
SELECT B.BOOK_ID AS bookId, B.ISBN AS isbn, B.TITLE AS title, B.AUTHOR AS author, B.PUBLISHER AS publisher, B.PUBLISH_DATE AS publishDate, B.CATEGORY_CD AS categoryCd, C.CATEGORY_NM AS categoryNm, B.LOCATION AS location, B.LOAN_YN AS loanYn, B.REG_DATE AS regDate FROM TB_BOOK B LEFT JOIN TB_CATEGORY C ON B.CATEGORY_CD = C.CATEGORY_CD
AND B.TITLE LIKE CONCAT('%', #{title}, '%')
AND B.AUTHOR LIKE CONCAT('%', #{author}, '%')
AND B.CATEGORY_CD = #{categoryCd}
AND B.LOAN_YN = #{loanYn}
ORDER BY B.REG_DATE DESC LIMIT #{firstIndex}, #{pageSize}

SELECT COUNT(*)
FROM TB_BOOK B


        AND B.TITLE LIKE CONCAT('%', #{title}, '%')


        AND B.AUTHOR LIKE CONCAT('%', #{author}, '%')


        AND B.CATEGORY_CD = #{categoryCd}


        AND B.LOAN_YN = #{loanYn}
